    if (f === 'na') return C.na ? `${s(C.na, 'пропуск', 'пропуска', 'пропусков')}, ${pct(C.na, n)}.` : 'Пропусков нет — ни пустых ячеек, ни строк вроде «N/A».';
    if (f === 'dtype') return `${C.dtype} совпадает со смыслом: ${KL[C.kind]}.`;
