        return `Чаще всего: ${C.top.map(t => `${typeof t[0] === 'number' ? fmtN(t[0]) : `«${esc(t[0])}»`} ×${fmtD(t[1])}`).join(', ')}.${C.min !== undefined && C.min !== null ? ` Минимум ${fmtN(C.min)}, медиана ${fmtN(C.med)}, максимум ${fmtN(C.max)}.` : ''}`;
